describe("render", () => {
  test("escapes values, supports raw values, missing values, and comments", () => {
    expect(render("{{x}}|{{{x}}}|{{missing}}{{! ignore }}", { x: `&<>\"'` }))
      .toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'|");
  });

  test("preserves whitespace exactly", () => {
    expect(render(" a\n  {{x}} \n", { x: "b" })).toBe(" a\n  b \n");
  });

