    const cases = [
      "x\n{{else}}",
      "{{#if x}}{{else}}{{else}}{{/if}}",
      "{{#if x}}{{/each}}",
      "{{#wat x}}{{/wat}}",
      "{{#each x}}",
      "{{/if}}",
